package docker

// In-container paths and env names. These MUST match the sandbox-base
// entrypoint generated by pkg/sandbox/k8s/overlay_entrypoint.go. Docker
// duplicates the constants instead of importing k8s (import cycle).
const (
	mountLayers  = "/mnt/troupe-layers"
	mountUppers  = "/mnt/troupe-uppers"
	mountOverlay = "/var/troupe/overlay"
	mountUpper   = mountOverlay + "/upper"
	mountWork    = mountOverlay + "/work"
	mountRootfs  = "/sandbox/rootfs"

	troupeShell = "/usr/local/bin/troupe-shell"

	envSessionID  = "TROUPE_SESSION_ID"
	envLayerChain = "TROUPE_LAYER_CHAIN"
	envUpperDir   = "TROUPE_UPPER_DIR"
	envWorkDir    = "TROUPE_WORK_DIR"
	envLayersDir  = "TROUPE_LAYERS_DIR"
	envUppersDir  = "TROUPE_UPPERS_DIR"
	envHandoff    = "TROUPE_HANDOFF"
	envHandoffArg = "TROUPE_HANDOFF_ARGS"

	layerChainFile = "layer-chain.txt"
)
